<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {api,type Row} from './api';
const rules=ref<Row|null>(null),urge=ref<Row|null>(null),days=ref<Row[]>([]),year=ref(new Date().getFullYear()),text=ref(''),error=ref(''),message=ref(''),busy=ref(false);
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function calendar(){days.value=await api('/admin/work-calendar?year='+year.value)}
onMounted(()=>run(async()=>{[rules.value,urge.value]=await Promise.all([api('/admin/attendance-rules'),api('/admin/urge-config')]);await calendar()}));
async function save(){await api('/admin/attendance-rules','PUT',rules.value);message.value='考勤规则已保存'}
async function batch(){const result=await api('/admin/work-calendar/batch','POST',{text:text.value});message.value=`成功 ${result.success} 行，失败 ${result.failed} 行`;error.value=result.rows.filter((r:Row)=>!r.success).map((r:Row)=>`第 ${r.line} 行：${r.message}`).join('；');await calendar()}
</script>
<template><section class="card"><h2>考勤规则</h2><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p>
<form v-if="rules" @submit.prevent="run(save)"><label><input v-model="rules.enabled" type="checkbox" />启用迟到、早退、缺卡统计</label><label>标准上班时间<input v-model="rules.work_start" type="time" required /></label><label>标准下班时间<input v-model="rules.work_end" type="time" required /></label><label>迟到宽限（分钟）<input v-model.number="rules.late_grace_minutes" type="number" min="0" max="240" required /></label><label>早退宽限（分钟）<input v-model.number="rules.early_grace_minutes" type="number" min="0" max="240" required /></label><label>工作日（1=周一，英文逗号分隔）<input v-model="rules.workdays" required pattern="[1-7](,[1-7]){0,6}" /></label><label>统计生效日期<input v-model="rules.effective_from" type="date" required /></label><button :disabled="busy">{{busy?'提交中…':'保存考勤规则'}}</button></form>
<h3>工作日历</h3><p>请以国务院办公厅当年通知为准。HOLIDAY 免打卡，WORKDAY 调休补班。每行：日期,类型,名称；每次最多400行。重复日期覆盖。</p><label>日历年份<input v-model.number="year" type="number" min="1" max="9998" /></label><button :disabled="busy" @click="run(calendar)">查询日历</button>
<label>批量导入日历<textarea v-model="text" rows="5" placeholder="2026-10-01,HOLIDAY,国庆节" /></label><button :disabled="busy" @click="text='2026-10-01,HOLIDAY,国庆节\n2026-10-10,WORKDAY,调休上班'">填入示例</button><button :disabled="busy||!text.trim()" @click="run(batch)">批量保存日历</button>
<p v-if="!days.length">暂无特殊日期，按默认工作日统计</p><p v-for="d in days" :key="d.day">{{d.day}} · {{d.kind==='HOLIDAY'?'节假日':'调休补班'}} · {{d.name}} <button :disabled="busy" @click="run(async()=>{await api('/admin/work-calendar/'+d.day,'DELETE');await calendar()})">删除日期</button></p>
<h3>审批催办配置</h3><form v-if="urge" @submit.prevent="run(async()=>{await api('/admin/urge-config','PUT',urge);message='催办配置已保存'})"><label>手动催办冷却（分钟）<input v-model.number="urge.urge_cooldown_minutes" type="number" min="1" max="10080" required /></label><label><input v-model="urge.auto_urge_enabled" type="checkbox" />启用超时自动催办</label><label>超时阈值（小时）<input v-model.number="urge.auto_urge_hours" type="number" min="1" max="8760" required /></label><label>重复间隔（小时，0=不重复）<input v-model.number="urge.auto_urge_repeat_hours" type="number" min="0" max="8760" required /></label><p>每10分钟巡检，改派后重新计时。通知进入消息中心并使用现有 Android FCM。</p><button :disabled="busy">保存催办配置</button></form></section></template>
